<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Bootstrap\CanonicalJson;use App\Imperium\Runtime\Foundry\SubordinateConstructionCaseService;use PHPUnit\Framework\TestCase;
final class SubordinateConstructionCaseServiceTest extends TestCase{public function testOpensOneIndependentCasePerExactResolution():void{$root=sys_get_temp_dir().'/imperium-subordinate-cases-'.bin2hex(random_bytes(6));$refs=[];foreach([['hagiography','Chronicler'],['studium','Notary']]as[$office,$class]){$id=$office.'-subordinate-resolution-'.str_repeat('a',20);$decision=['required_specializations'=>[$class.' exact work'],'seat_requirements'=>['versioned Seat']];$r=['schema'=>'imperium.authorship-subordinate-resolution/v1','resolution_id'=>$id,'instance_id'=>'imperium-test','office'=>$office,'acceptance_id'=>$office.'-acceptance','commission_id'=>$office.'-commission','subordinate_staff_class'=>$class,'decision'=>$decision,'status'=>'PENDING_CURIA_SUBORDINATE_CONSTRUCTION_AUTHORIZATION','sealed'=>true,'construction_authority'=>false,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false];$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$dir=$root.'/var/imperium/offices/'.$office.'/subordinate-resolutions';mkdir($dir,0770,true);file_put_contents($dir.'/'.$id.'.json',json_encode($r,JSON_THROW_ON_ERROR));$refs[]=['resolution_id'=>$id,'record_digest'=>$r['record_digest'],'office'=>$office,'acceptance_id'=>$r['acceptance_id'],'commission_id'=>$r['commission_id'],'subordinate_staff_class'=>$class,'required_specializations'=>$decision['required_specializations']];}$id='foundry-subordinate-acceptance-'.str_repeat('b',20);$a=['schema'=>'imperium.foundry-subordinate-construction-authorization-acceptance/v1','acceptance_id'=>$id,'instance_id'=>'imperium-test','guildhall_commission_id'=>'guildhall-subordinate-construction-commission-'.str_repeat('c',20),'guildhall_commission_digest'=>'guildhall-commission-digest','actor'=>['seat'=>'foundry.artificer','manifestation_id'=>'artificer','occupancy_generation'=>1],'authorized_resolutions'=>$refs,'disposition'=>'ACCEPTED_FOR_EXACT_SUBORDINATE_CONSTRUCTION','recipient_acceptance'=>true,'construction_authority'=>true,'construction_authority_exercisable'=>true,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false];$a['record_digest']=hash('sha256',CanonicalJson::encode($a));$dir=$root.'/var/imperium/offices/foundry/subordinate-construction-acceptances';mkdir($dir,0770,true);file_put_contents($dir.'/'.$id.'.json',json_encode($a,JSON_THROW_ON_ERROR));try{$service=new SubordinateConstructionCaseService($root);$out=$service->open($id);self::assertSame($out,$service->open($id));self::assertCount(2,$out['cases']);self::assertSame(['hagiography','studium'],array_column($out['cases'],'office'));self::assertSame(['Chronicler','Notary'],array_column($out['cases'],'subordinate_staff_class'));self::assertSame('OPEN_PENDING_PERSONA_SPECIFICATION',$out['cases'][0]['status']);self::assertSame(['Chronicler exact work'],$out['cases'][0]['subordinate_requirements']['required_specializations']);self::assertFalse($out['cases'][0]['persona_selection_authority']);self::assertFalse($out['cases'][0]['profile_approval_authority']);self::assertFalse($out['cases'][0]['spawning_authority']);self::assertFalse($out['cases'][0]['execution_authority']);}finally{$this->removeTree($root);}}private function removeTree(string $path):void{if(!is_dir($path))return;foreach(array_diff(scandir($path)?:[],['.','..'])as$entry){$child=$path.'/'.$entry;is_dir($child)?$this->removeTree($child):unlink($child);}rmdir($path);}}
